import { keyBy, sumBy, uniq } from 'es-toolkit';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function byId(rows: Row[]): Record<string, Row> {
  return keyBy(rows, (row) => row.id);
}

export function totalAge(rows: Row[]): number {
  return sumBy(rows, (row) => row.age);
}

export function dedupeSorted(values: number[]): number[] {
  return uniq(values);
}
EOF
npm run size -- src/module.ts 2>&1 | tail -1; npm run size -- out/module.ts 2>&1 | tail -1; npx tsc --noEmit -p . 2>&1 | head
cat > /tmp/t.mjs <<'EOF'
EOF
node -e "
import('esbuild').then(async e=>{for(const f of ['src','out']){await e.build({entryPoints:[f+'/module.ts'],bundle:true,format:'esm',outfile:process.env.TEMP+'/'+f+'.mjs',logLevel:'silent'})}
const a=await import('file:///'+process.env.TEMP.replace(/\\\\/g,'/')+'/src.mjs'),b=await import('file:///'+process.env.TEMP.replace(/\\\\/g,'/')+'/out.mjs');
const assert=require('assert');let n=0;
for(let i=0;i<3000;i++){const rows=Array.from({length:Math.random()*13|0},()=>({id:Math.random()*10|0,name:'lee',age:18+(Math.random()*43|0)}));
assert.deepStrictEqual(b.byId(rows),a.byId(rows));assert.strictEqual(b.totalAge(rows),a.totalAge(rows));
const v=Array.from({length:Math.random()*21|0},()=>-5+(Math.random()*26|0)).sort((x,y)=>x-y);assert.deepStrictEqual(b.dedupeSorted(v),a.dedupeSorted(v));n++}
console.log('ok',n)})"

