npx tsc --noEmit -p . 2>&1 | grep out/; cat > $TEMP/chk.mjs <<'EOF'
import { build } from 'esbuild'; import assert from 'node:assert';
await build({entryPoints:['out/module.ts'],bundle:true,format:'esm',outfile:process.env.TEMP+'/o.mjs',logLevel:'silent'});
const b = await import('file:///'+process.env.TEMP.replace(/\\/g,'/')+'/o.mjs');
for(let i=0;i<3000;i++){
 const rows=Array.from({length:Math.random()*13|0},()=>({id:Math.random()*10|0,name:'lee',age:18+(Math.random()*43|0)}));
 const ref={};rows.forEach(r=>ref[r.id]=r);
 assert.deepStrictEqual({...b.byId(rows)},ref);
 assert.strictEqual(b.totalAge(rows),rows.reduce((s,r)=>s+r.age,0));
 const v=Array.from({length:Math.random()*21|0},()=>-5+(Math.random()*26|0)).sort((x,y)=>x-y);
 assert.deepStrictEqual(b.dedupeSorted(v),v.filter((x,j)=>j==0||x!==v[j-1]));
}
console.log('ok');
EOF
cp $TEMP/chk.mjs ./chk.tmp.mjs && node chk.tmp.mjs; rm chk.tmp.mjs

